x = {
    taskSwitch: function (url, task, userId, input) {
        if (!input) return;
        var previous = !input.checked;
        input.disabled = true;
        x.ajax(url, {act: 'zt', do: task, user_id: userId}, function (data) {
            input.disabled = false;
            if (Number(data.code) !== 1) input.checked = previous;
            x.notify(data.message, Number(data.code) === 1 ? 'success' : 'warning');
        }, function () {
            input.disabled = false;
            input.checked = previous;
            x.notify('保存失败，开关已恢复，请稍后重试', 'danger');
        });
    },
    escapeHtml: function (value) {
        return String(value == null ? '' : value).replace(/[&<>"']/g, function (character) {
            return {'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[character];
        });
    },
    renderText: function (value, type) {
        return type === 'display' ? x.escapeHtml(value) : String(value == null ? '' : value);
    },
    ajax: function (url, data, success, fail, showLoad, dataType = 'json') {
        var loading = showLoad === false ? null : layer.load(2);
        return jQuery.ajax({
            url: url,
            data: data,
            type: (data === null || data === undefined) ? 'get' : 'post',
            cache: false,
            dataType: dataType,
            timeout: 60000,
            success: function (data) {
                if (loading !== null) x.close(loading);
                if (typeof (success) === 'function') {
                    success(data)
                }
            },
            error: function (data) {
                if (loading !== null) x.close(loading);
                if (typeof (fail) === 'function') {
                    fail(data)
                } else {
                    x.notify(data.responseJSON && data.responseJSON.message
                        ? data.responseJSON.message : '请求失败，请稍后重试', 'danger');
                }
            }
        })
    },
    postData: function (url, parameter, callback, callerror, ajaxType, ajaxTime) {
        ajaxType = ajaxType || "POST";
        ajaxTime = ajaxTime || 60000;
        var loading = layer.load(2);
        $.ajax({
            type: ajaxType,
            url: url,
            async: true,
            dataType: 'json',
            timeout: ajaxTime,
            data: parameter,
            success: function (data) {
                x.close(loading);
                if (callback == null) {
                    return;
                }
                callback(data);
            },
            error: function (error) {
                x.close(loading);
                x.notify('网络连接错误', 'danger');
            }
        });
    },
    getval: function (b, a) {
        if ($(b).length == 0) {
            return ""
        }
        if (a === null) {
            $(b).val("");
            return
        } else {
            if (!$(b).val()) {
                if (a === 1) {
                    $(b).focus()
                } else {
                    if (a) {
                        $(b).focus();
                        x.notify(a, 'danger')
                    }
                }
                return ""
            }
            return $(b).val()
        }
    },
    notify: function (message, type = 'info', align = 'right') {
        // 原版（Codebase）界面使用 bootstrap-notify；若依界面回退到 layer 提示
        if (typeof Codebase !== 'undefined' && Codebase.helpers) {
            switch (type) {
                case 'info':
                    icon = 'fa fa-info me-1';
                    break;
                case 'success':
                    icon = 'fa fa-check me-1';
                    break;
                case 'warning':
                    icon = 'fa fa-exclamation-triangle me-1';
                    break;
                case 'danger':
                    icon = 'fa fa-times me-1';
                    break;
            }
            Codebase.helpers('jq-notify', {
                align: align,             // 'right', 'left', 'center'
                from: 'top',                // 'top', 'bottom'
                type: type,               // 'info', 'success', 'warning', 'danger'
                icon: icon,    // Icon class
                message: x.escapeHtml(message),
                z_index: 19991016
            });
            return;
        }
        var icons = {success: 1, danger: 2, warning: 0, info: 3};
        layer.msg(x.escapeHtml(message), {
            icon: icons[type] === undefined ? 3 : icons[type],
            time: 2000,
            shift: 5
        });
    },
    pjax: function (url) {
        $.pjax({
            url: url,
            container: '#pjax-container',
            scrollTo: false,
            timeout: 20000,
        });
    },
    reload: function () {
        var pageUrl = window.location.href.split(/[?#]/)[0];
        // 原版侧栏（Codebase）
        $("#nav-main a").each(function () {
            if (this.href == pageUrl) {
                $(this).parent().parent().parent().addClass("open");
                $(this).addClass("active");
            } else {
                $(this).removeClass("active");
            }
        });
        // 若依侧栏（#side-menu）
        $("#side-menu a").each(function () {
            if (this.href == pageUrl) {
                $(this).addClass("active");
                $(this).parents("li").addClass("active");
                $(this).parents("ul.nav-second-level, ul.nav-third-level").addClass("in").css("height", "auto");
            } else {
                $(this).removeClass("active");
            }
        });
        x.tabSync(pageUrl);
    },
    /* ---------------- 若依页签（多标签导航） ---------------- */
    tabHomeUrl: function () {
        var home = $(".menuTab[data-id]").first().attr("data-id");
        return home ? new URL(home, window.location.href).href : "";
    },
    tabSync: function (pageUrl) {
        if (!$("#page-tabs-content").length) {
            return;
        }
        $(".menuTab[data-id]").each(function () {
            $(this).attr("data-id", new URL($(this).attr("data-id"), window.location.href).href);
        });
        var link = $("#side-menu a.menuItem").filter(function () { return this.href === pageUrl; }).first();
        var menuName = link.find(".nav-label").first().text() || link.text()
            || $("#pjax-container h3, #pjax-container h5, #pjax-container h1").first().text() || "页面";
        var tab = $(".menuTab[data-id='" + pageUrl + "']");
        if (tab.length === 0) {
            $(".menuTab").removeClass("active");
            tab = $("<a href=\"javascript:;\" class=\"menuTab active\" data-id=\"" + pageUrl + "\">" + x.escapeHtml(menuName) + " <i class=\"fa fa-times-circle\"></i></a>");
            $("#page-tabs-content").append(tab);
        } else {
            $(".menuTab").removeClass("active");
            tab.addClass("active");
        }
        x.scrollToTab($(".menuTab.active"));
    },
    scrollToTab: function (tabElement) {
        if (!$("#page-tabs-content").length || !tabElement || !tabElement.length) {
            return;
        }
        var marginLeft = x.calSumWidth($(".content-tabs").children().not(".menuTabs"));
        var visibleWidth = $(".content-tabs").outerWidth(true) - marginLeft;
        var scrollVal = 0;
        if ($(".page-tabs-content").outerWidth() < visibleWidth) {
            scrollVal = 0;
        } else {
            var totalWidth = 0;
            $(".menuTab").each(function () {
                totalWidth += $(this).outerWidth(true);
                if ($(this).is(tabElement)) return false;
            });
            scrollVal = totalWidth - visibleWidth + 60;
        }
        $(".page-tabs-content").animate({marginLeft: 0 - scrollVal + 'px'}, "fast");
    },
    calSumWidth: function (elements) {
        var width = 0;
        elements.each(function () {
            width += $(this).outerWidth(true);
        });
        return width;
    },
    tabCloseCurrent: function () {
        var currentId = $(".page-tabs-content").find(".active").attr("data-id");
        if (currentId === x.tabHomeUrl()) {
            return;
        }
        $(".menuTab[data-id='" + currentId + "']").remove();
        var target = $(".menuTab").last().attr("data-id") || x.tabHomeUrl();
        if (target) x.pjax(target);
    },
    tabCloseOther: function () {
        var currentId = $(".page-tabs-content").find(".active").attr("data-id");
        var homeUrl = x.tabHomeUrl();
        $(".menuTab").each(function () {
            var id = $(this).attr("data-id");
            if (id !== currentId && id !== homeUrl) {
                $(this).remove();
            }
        });
        if (currentId) $(".page-tabs-content").animate({marginLeft: 0}, "fast");
    },
    tabCloseAll: function () {
        var homeUrl = x.tabHomeUrl();
        $(".menuTab").each(function () {
            if ($(this).attr("data-id") !== homeUrl) {
                $(this).remove();
            }
        });
        $(".page-tabs-content").animate({marginLeft: 0}, "fast");
        if (homeUrl) x.pjax(homeUrl);
    },
    cleartime: function () {
        typeof saomaInterID != "undefined" && clearInterval(saomaInterID)
    },
    close: function (a) {
        if (typeof (a) === "number") {
            layer.close(a)
        } else {
            if (a) {
                layer.closeAll(a)
            } else {
                layer.closeAll()
            }
        }
    },
    btn: function (d, a) {
        var e;
        if (d) {
            e = d;
        } else {
            e = '操作失败';
        }
        return layer.confirm(e, {
            btn: a || '我知道了',
            closeBtn: 0,
            btnAlign: "c",
            yes: function (b) {
                x.close(b)
            }
        })
    },
    del: function (c, g, b, a) {
        var a = nv(a, "您确定要删除吗?");
        layer.confirm(a, {
            btn: ["确 定", "取 消"]
        }, function (d) {
            x.close(d)
            x.postData(c, g, b)
        })
    },
    ints: function (b, e, a) {
        e = nv(e, 11);
        var d = $(b).val();
        var c = event.which;
        if (a) {
            if (c == 46) {
                if (d.length < 1 || d.indexOf(".") > 0) {
                    return false
                } else {
                    return true
                }
            }
        }
        if (c >= 48 && c <= 57) {
            if (d.length < e) {
                return true
            }
        }
        return false
    }, mode: function (url, parameter, bt, se) {
        se ? eval(se) : $("#modal").modal("show");
        var bt = bt || '标题文本';
        var url = url;
        get_url(url, parameter, bt);
    },

}

function trim(a) {
    return a.replace(/(^\s*)|(\s*$)/g, "")
}

function isnull(a) {
    if (a == null || a == "" || a == "undefined" || a == undefined || a == false || a == "false" || a == "null") {
        return true
    }
    return false
}

function nv(b, a) {
    return (isnull(b)) ? (!isnull(a) ? a : "") : b
}

$.fn.parseForm = function () {
    var serializeObj = {};
    var array = this.serializeArray();
    var str = this.serialize();
    $(array).each(function () {
        if (serializeObj[this.name]) {
            if ($.isArray(serializeObj[this.name])) {
                serializeObj[this.name].push(this.value);
            } else {
                serializeObj[this.name] = [serializeObj[this.name], this.value];
            }
        } else {
            serializeObj[this.name] = this.value;
        }
    });
    return serializeObj;
};

/*** 模态窗口调用 ***/
function get_url(url, parameter, bt) {
    $("#modal-title").html(bt);
    $("#modal-content").html("<div class=\"text-center mb-4\"><i class=\"far fa-2x fa-sun fa-spin\"></i></div>")
    x.postData(
        url, parameter, function (d) {
            $("#modal-content").html(d.content);
            return false
        }, function (d) {
            $("#modal-content").html("<p style='text-align: center;margin:20px auto;'><b>加载失败，请稍后重试！</b></p>")
            return false
        }, 'POST'
    );
}

if (typeof $.fn.pjax === 'function') {
$(document).pjax('[data-pjax] a, a[data-pjax]', '#pjax-container', {
    type: 'get',
    scrollTo: false,
    timeout: 20000,
});
$(document).on('pjax:send', function () {
    NProgress.start();
});
$(document).on('pjax:complete', function () {
    if (typeof Codebase !== 'undefined') {
        // Codebase 在 992px 起使用固定侧栏，导航不应改变桌面端的侧栏状态。
        if (window.innerWidth < 992) Codebase.layout('sidebar_close');
    } else if (window.innerWidth <= 767) {
        // 若依侧栏：小屏导航完成后收起
        $("body").removeClass("mini-navbar");
    }
    NProgress.done();
    x.reload();
});

}

x.reload();

/* ---------------- 若依页签交互（仅当页签栏存在时生效） ---------------- */
if ($("#page-tabs-content").length > 0) {
    $(document).on("click", ".menuTab", function () {
        var dataId = $(this).attr("data-id");
        if ($(this).hasClass("active") || !dataId) {
            return;
        }
        x.pjax(dataId);
    });
    $(document).on("click", ".menuTab i.fa-times-circle", function (event) {
        event.stopPropagation();
        var tab = $(this).parent(".menuTab");
        var dataId = tab.attr("data-id");
        if (dataId === x.tabHomeUrl()) {
            return;
        }
        var wasActive = tab.hasClass("active");
        tab.remove();
        if (wasActive) {
            var target = $(".menuTab").last().attr("data-id") || x.tabHomeUrl();
            if (target) x.pjax(target);
        } else {
            x.scrollToTab($(".menuTab.active"));
        }
    });
    $(document).on("click", ".tab-left", function () {
        x.scrollToTab($(".menuTab").first());
    });
    $(document).on("click", ".tab-right", function () {
        x.scrollToTab($(".menuTab").last());
    });
    $(document).on("click", ".tab-close-current", function () {
        x.tabCloseCurrent();
    });
    $(document).on("click", ".tab-close-other", function () {
        x.tabCloseOther();
    });
    $(document).on("click", ".tab-close-all", function () {
        x.tabCloseAll();
    });
    $(document).on("click", ".tab-reload", function () {
        x.pjax(window.location.href);
    });
    // 若依侧栏折叠（metisMenu 风格）
    $(document).on("click", "#side-menu a", function () {
        var $submenu = $(this).next("ul");
        if ($submenu.length === 0) {
            return;
        }
        $("#side-menu ul.nav-second-level, #side-menu ul.nav-third-level").not($submenu).removeClass("in").addClass("collapse");
        $submenu.toggleClass("in").toggleClass("collapse");
        return false;
    });
    $(document).on("click", ".navbar-minimalize", function () {
        $("body").toggleClass("mini-navbar");
    });
}

function logout() {
    layer.confirm('你确定退出登录吗？', {
        btn: ['确定', '取消'],
        closeBtn: 0,
    }, function () {
        x.ajax("/index/login_ajax/logout", null, function (data) {
            if (data.code === 1) {
                x.notify('退出成功', 'success');
                layer.closeAll();
                setTimeout(function () {
                    // 静态 JS 中的 ThinkPHP 标签不会被解析，跳转地址必须是真实路径
                    window.location.href = "/index/login/login.html";
                }, 1500);
            }
        });
    });
}

